package com.nextrade.service; import com.nextrade.common.event.DomainEvent; import com.nextrade.domain.repository.EventOutbox; import java.util.*; public final class OutboxEventPublisher {private final EventOutbox outbox;public OutboxEventPublisher(EventOutbox outbox){this.outbox=outbox;}public void publish(DomainEvent event){outbox.append(event);}public void publishAll(Collection<? extends DomainEvent> events){outbox.appendAll(events);}}
